<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { readFeature, writeFeature, featureError, type Job, type Page } from '@/services/additionalFeatures'
import OpsPager from './OpsPager.vue'
import './operations.css'
const services=[{key:'auth',name:'Email tài khoản',path:'/api/users/admin/operations'},{key:'wallet',name:'Sự kiện ví → Kafka',path:'/api/nihongo-user/admin/operations'},{key:'mail',name:'Email biên nhận ví',path:'/api/notification/admin/operations'}]
const health=ref<Record<string,{pending:number;serverTime:number}|null>>({}),selected=ref(services[0]!),rows=ref<Page<Job>>({content:[],number:0,totalPages:0,totalElements:0}),busy=ref(false),error=ref(''),reason=ref(''),message=ref('')
async function refresh(){busy.value=true;await Promise.all(services.map(async service=>{try{health.value[service.key]=await readFeature(service.path)}catch{health.value[service.key]=null}}));busy.value=false}
async function load(page=0){error.value='';try{rows.value=await readFeature(`${selected.value.path}/queue`,{page})}catch(cause){error.value=featureError(cause)}}
async function select(service:typeof services[number]){selected.value=service;rows.value={content:[],number:0,totalPages:0,totalElements:0};await load()}
async function retry(row:Job){if(busy.value||reason.value.trim().length<10)return;busy.value=true;error.value='';try{await writeFeature(`${selected.value.path}/queue/${row.id}/retry`,{reason:reason.value.trim()});message.value='Đã đưa tác vụ về lịch xử lý gần nhất.';await load(rows.value.number);await refresh()}catch(cause){error.value=featureError(cause)}finally{busy.value=false}}
function time(value:string|number){return new Date(value).toLocaleString('vi-VN')}
onMounted(async()=>{await refresh();await load()})
</script>
<template><div class="ops-page"><header class="ops-heading"><div><h1>Trung tâm vận hành</h1><p>Theo dõi hàng chờ, retry và các service phản hồi. Số liệu không thay thế kiểm tra kết nối broker/SMTP.</p></div><button class="ops-button secondary" :disabled="busy" @click="refresh">Tải trạng thái</button></header><div class="ops-grid"><button v-for="service in services" :key="service.key" class="ops-panel" @click="select(service)"><h2>{{ service.name }}</h2><p v-if="health[service.key]">Đang chờ: {{ health[service.key]?.pending }}</p><p v-else class="ops-error">Chưa lấy được trạng thái</p></button></div><p v-if="error" class="ops-error" role="alert">{{ error }}</p><p v-if="message" class="ops-success" role="status">{{ message }}</p><section class="ops-panel"><h2>{{ selected.name }}</h2><label>Lý do retry (10–500 ký tự)<input v-model="reason" minlength="10" maxlength="500"></label><p class="ops-muted">Không retry tác vụ đang được xử lý hoặc liên kết email đã hết hạn. Thao tác được ghi nhật ký.</p><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>ID</th><th>Lần thử</th><th>Lần xử lý tới</th><th>Hết hạn</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="row in rows.content" :key="row.id"><td>{{ row.id }}</td><td>{{ row.attempts }}</td><td>{{ time(row.nextAttempt) }}</td><td>{{ row.expiresAt?time(row.expiresAt):'—' }}</td><td>{{ row.leased?'Đang xử lý':'Chờ' }}</td><td><button class="ops-button" :disabled="busy||row.leased||reason.trim().length<10||!!row.expiresAt && row.expiresAt<=Date.now()" @click="retry(row)">Retry</button></td></tr></tbody></table></div><p v-if="!rows.content.length" class="ops-empty">Không có tác vụ đang chờ.</p><OpsPager :page="rows.number" :total-pages="rows.totalPages" :total-elements="rows.totalElements" :busy="busy" @change="load" /></section></div></template>
